68	/// Every model. openai-node raises on an Anthropic stream (it iterates `chunk.choices`), so pair
69	/// models with the stream format through [`runners`] where that matters.
70	pub const MODELS: &[(&str, Model)] = &[
71	    ("openai-python", openai_python),
72	    ("openai-node", openai_node),
73	    ("langchain", langchain),
74	    ("anthropic-python", anthropic_python),
75	];
76	
77	const OPENAI_RUNNERS: &[(&str, Runner)] = &[("openai-python", run_openai_python), ("openai-node", run_openai_node), ("langchain", run_langchain)];
78	const ANTHROPIC_RUNNERS: &[(&str, Runner)] = &[("anthropic-python", run_anthropic_python)];
79	
80	/// The models of the clients that read `format`.
81	pub fn runners(format: Format) -> &'static [(&'static str, Runner)] {
82	    match format {
83	        Format::AnthropicMessages => ANTHROPIC_RUNNERS,
84	        _ => OPENAI_RUNNERS,
85	    }
86	}
