88	/// The model kind of a decided call.
89	pub fn kind_of(k: ToolCallKind) -> &'static str {
90	    match k {
91	        ToolCallKind::Function => "function",
92	        ToolCallKind::Custom => "custom",
93	        ToolCallKind::LegacyFunctionCall => "legacy",
94	        ToolCallKind::AnthropicToolUse => "tool_use",
95	        _ => "other",
96	    }
97	}
98	
99	/// A decided call in the models' terms. A `tool_use` call's arguments are compared as parsed JSON,
100	/// because anthropic-python hands the client the parsed `input`, not the string.
101	pub fn as_model_call(c: &ToolCall) -> ModelCall {
102	    ModelCall {
103	        choice: c.choice,
104	        kind: kind_of(c.kind),
105	        name: c.name.clone(),
106	        arguments: c.arguments.clone(),
107	        parsed: false,
108	    }
109	}
110	
111	/// Whether a model call's arguments match a decided call's. The decider sees `{}` for empty
112	/// function arguments (the core's rule), so a client's raw `""` matches it. A `parsed` model value
113	/// is compared with the parsed decided string. The match is exact, also for the snapshot at an
114	/// excused raise: a prefix of allowed arguments can be a call that an argument-reading policy
115	/// (SMA-752) denies, and the gateway never asks the decider about it. The exception is kind
116	/// `other`: its arguments are not compared, because the decided form is the raw entry (spec § 4,
117	/// § 9).
118	fn arguments_match(mc: &ModelCall, decided: &ModelCall) -> bool {
119	    if mc.kind == "other" {
120	        return true; // the decided form of kind Other is the raw entry
121	    }
122	    if mc.parsed {
123	        let full = if decided.arguments.is_empty() {
124	            Ok(json!({}))
125	        } else {
126	            serde_json::from_str::<Value>(&decided.arguments)
127	        };
128	        let (Ok(full), Ok(got)) = (full, serde_json::from_str::<Value>(&mc.arguments)) else {
129	            return false;
130	        };
131	        return got == full;
132	    }
133	    mc.arguments == decided.arguments || (mc.arguments.is_empty() && decided.arguments == "{}")
134	}
135	
136	/// Invariant I1 as property P1 states it (spec § 2, § 8.1). Every call a client model derives from
137	/// `out` matches a distinct call the decider allowed, by choice, kind, name and arguments
138	/// (arguments are not compared for kind `other`, whose decided form is the raw entry).
139	///
140	/// A model that raises on `out` is an error unless the interceptor dropped a record or took an
141	/// `on_failure` path (`core_failed`), or the client already raises on the upstream bytes `input`:
142	/// a correct interceptor must not make a working client fail. An excused raise is still checked:
143	/// the client may have acted on calls before it raised, so every call in its snapshot must match
144	/// a decided, allowed call exactly. A strict prefix of an allowed call is never accepted: the
145	/// gateway never asked the decider about it, and an argument-reading policy (SMA-752) may deny it.
146	pub fn check_i1(format: Format, input: &[u8], out: &[u8], decided: &[(ToolCall, Decision)], core_failed: bool) -> Result<(), String> {
147	    let allowed: Vec<ModelCall> = decided.iter().filter(|(_, d)| d.is_allow()).map(|(c, _)| as_model_call(c)).collect();
148	    let show = || String::from_utf8_lossy(out).into_owned();
149	    for (model, run) in runners(format) {
150	        let r = run(out);
151	        match &r.error {
152	            Some(_) if core_failed || run(input).error.is_some() => {} // excused; the snapshot is still checked
153	            Some(e) => return Err(format!("{model} raised on the output: {e}\n{}", show())),
154	            None => {}
155	        }
156	        let mut left = allowed.clone();
157	        for mc in r.calls {
158	            let hit = left.iter().position(|a| a.choice == mc.choice && a.kind == mc.kind && a.name == mc.name && arguments_match(&mc, a));
159	            match hit {
160	                Some(i) => {
161	                    left.remove(i);
162	                }
163	                None => return Err(format!("{model} runs an undecided or blocked call {mc:?}\nallowed: {allowed:?}\n{}", show())),
164	            }
165	        }
166	    }
167	    Ok(())
168	}
