170	// ---- SSE decoders ------------------------------------------------------------------------------
171	
172	/// One dispatched SSE event.
173	#[derive(Debug, Clone, PartialEq, Eq)]
174	pub struct Sse {
175	    pub event: Option<String>,
176	    pub data: String,
177	}
178	
179	/// Lines split at CRLF, CR or LF; the last element is the unterminated rest (maybe empty).
180	fn lines(bytes: &[u8]) -> (Vec<&[u8]>, &[u8]) {
181	    let mut out = Vec::new();
182	    let mut start = 0;
183	    let mut i = 0;
184	    while i < bytes.len() {
185	        match bytes[i] {
186	            b'\n' => {
187	                out.push(&bytes[start..i]);
188	                start = i + 1;
189	            }
190	            b'\r' => {
191	                out.push(&bytes[start..i]);
192	                if bytes.get(i + 1) == Some(&b'\n') {
193	                    i += 1;
194	                }
195	                start = i + 1;
196	            }
197	            _ => {}
198	        }
199	        i += 1;
200	    }
201	    (out, &bytes[start..])
202	}
203	
204	/// The `SSEDecoder` of openai-python and anthropic-python: lines split at CR, LF and CRLF, each
205	/// line decoded as strict UTF-8 (a bad byte raises), no BOM handling, a dispatch on a blank line
206	/// whenever an event name, data, an id or a retry was seen (so `event:` without `data:` dispatches
207	/// an empty data string), and no dispatch at the end of the stream without a blank line.
208	/// SOURCE: openai-python 3.40.0, src/openai/_streaming.py SSEDecoder.decode and
209	/// _SSELineDecoder; anthropic-python 2.3.0, src/anthropic/_streaming.py SSEDecoder.
210	pub fn py_events(bytes: &[u8]) -> Result<Vec<Sse>, String> {
211	    let (ls, rest) = lines(bytes);
212	    let mut out = Vec::new();
213	    let (mut event, mut data, mut last_id, mut retry): (Option<String>, Vec<String>, Option<String>, Option<i64>) = (None, Vec::new(), None, None);
214	    for raw in ls {
215	        let line = std::str::from_utf8(raw).map_err(|e| format!("UnicodeDecodeError: {e}"))?;
216	        if line.is_empty() {
217	            if event.as_deref().is_none_or(str::is_empty) && data.is_empty() && last_id.as_deref().is_none_or(str::is_empty) && retry.is_none() {
218	                continue;
219	            }
220	            out.push(Sse {
221	                event: event.take(),
222	                data: data.join("\n"),
223	            });
224	            data.clear();
225	            retry = None;
226	            continue;
227	        }
228	        if line.starts_with(':') {
229	            continue;
230	        }
231	        let (name, value) = match line.find(':') {
232	            Some(i) => (&line[..i], line[i + 1..].strip_prefix(' ').unwrap_or(&line[i + 1..])),
233	            None => (line, ""),
234	        };
235	        match name {
236	            "event" => event = Some(value.to_owned()),
237	            "data" => data.push(value.to_owned()),
238	            "id" if !value.contains('\0') => last_id = Some(value.to_owned()),
239	            "retry" => retry = value.parse().ok().or(retry),
240	            _ => {}
241	        }
242	    }
243	    std::str::from_utf8(rest).map_err(|e| format!("UnicodeDecodeError: {e}"))?;
244	    Ok(out)
245	}
