294	/// A reference WHATWG SSE splitter, independent of the crate's: (event, data) per record.
295	pub fn records(bytes: &[u8]) -> Vec<(Option<String>, Vec<u8>)> {
296	    let text = String::from_utf8_lossy(bytes);
297	    let text = text.strip_prefix('\u{feff}').unwrap_or(&text).replace("\r\n", "\n").replace('\r', "\n");
298	    let mut out = Vec::new();
299	    let (mut data, mut has, mut event): (Vec<u8>, bool, Option<String>) = (Vec::new(), false, None);
300	    for line in text.split('\n') {
301	        if line.is_empty() {
302	            if has {
303	                data.pop();
304	                if !data.is_empty() {
305	                    out.push((event.take(), std::mem::take(&mut data)));
306	                }
307	            }
308	            data.clear();
309	            has = false;
310	            event = None;
311	            continue;
312	        }
313	        if line.starts_with(':') {
314	            continue;
315	        }
316	        let (name, value) = match line.find(':') {
317	            Some(i) => (&line[..i], line[i + 1..].strip_prefix(' ').unwrap_or(&line[i + 1..])),
318	            None => (line, ""),
319	        };
320	        match name {
321	            "data" => {
322	                data.extend_from_slice(value.as_bytes());
323	                data.push(b'\n');
324	                has = true;
325	            }
326	            "event" => event = Some(value.to_owned()),
327	            _ => {}
328	        }
329	    }
330	    out
331	}
332	
333	pub fn payloads(bytes: &[u8]) -> Vec<Vec<u8>> {
334	    records(bytes).into_iter().map(|(_, d)| d).collect()
335	}
