337	// ---- Python and JavaScript value semantics -----------------------------------------------------
338	
339	fn py_truthy(v: Option<&Value>) -> bool {
340	    match v {
341	        None | Some(Value::Null) => false,
342	        Some(Value::Bool(b)) => *b,
343	        Some(Value::Number(n)) => n.as_f64() != Some(0.0),
344	        Some(Value::String(s)) => !s.is_empty(),
345	        Some(Value::Array(a)) => !a.is_empty(),
346	        Some(Value::Object(o)) => !o.is_empty(),
347	    }
348	}
349	
350	fn js_truthy(v: Option<&Value>) -> bool {
351	    match v {
352	        None | Some(Value::Null) => false,
353	        Some(Value::Bool(b)) => *b,
354	        Some(Value::Number(n)) => n.as_f64() != Some(0.0),
355	        Some(Value::String(s)) => !s.is_empty(),
356	        Some(_) => true,
357	    }
358	}
359	
360	/// A Python `int` (a `bool` is one), or `None` for anything else.
361	fn py_int(v: &Value) -> Option<i64> {
362	    match v {
363	        Value::Bool(b) => Some(i64::from(*b)),
364	        Value::Number(n) => n.as_i64().or_else(|| n.as_u64().map(|_| i64::MAX)),
365	        _ => None,
366	    }
367	}
368	
369	/// `list[idx]` with Python's negative indexing; `None` is an `IndexError`.
370	fn py_get(len: usize, idx: i64) -> Option<usize> {
371	    let len = i64::try_from(len).expect("small");
372	    let pos = if idx < 0 { idx + len } else { idx };
373	    (0..len).contains(&pos).then(|| usize::try_from(pos).expect("in range"))
374	}
375	
376	/// Where `list.insert(idx, x)` puts `x`.
377	fn py_insert_at(len: usize, idx: i64) -> usize {
378	    let l = i64::try_from(len).expect("small");
379	    let pos = if idx < 0 { (idx + l).max(0) } else { idx.min(l) };
380	    usize::try_from(pos).expect("clamped")
381	}
382	
383	fn py_scalar(v: &Value) -> bool {
384	    matches!(v, Value::String(_) | Value::Number(_) | Value::Bool(_))
385	}
386	
387	fn has_indexed_entries(v: &Value) -> bool {
388	    matches!(v, Value::Array(a) if a.iter().any(|e| matches!(e, Value::Object(o) if o.contains_key("index"))))
389	}
390	
391	fn py_add_numbers(a: &Value, b: &Value) -> Option<Value> {
392	    let int = |v: &Value| match v {
393	        Value::Bool(x) => Some(i64::from(*x)),
394	        Value::Number(n) => n.as_i64(),
395	        _ => None,
396	    };
397	    let float = |v: &Value| match v {
398	        Value::Bool(x) => Some(f64::from(u8::from(*x))),
399	        Value::Number(n) => n.as_f64(),
400	        _ => None,
401	    };
402	    if !matches!(a, Value::Number(_) | Value::Bool(_)) || !matches!(b, Value::Number(_) | Value::Bool(_)) {
403	        return None;
404	    }
405	    match (int(a), int(b)) {
406	        (Some(x), Some(y)) => Some(json!(x.wrapping_add(y))),
407	        _ => Some(json!(float(a)? + float(b)?)),
408	    }
409	}
