411	// ---- openai-python -----------------------------------------------------------------------------
412	
413	/// openai-python `accumulate_delta`. `index` and `type` are replaced, strings and numbers added,
414	/// dicts merged, indexed lists merged by `list[index]` (Python indexing, `insert` on IndexError).
415	/// A value of a different type is kept, not replaced.
416	/// SOURCE: openai-python 3.40.0, src/openai/lib/streaming/_deltas.py accumulate_delta.
417	fn accumulate_delta(acc: &mut Map<String, Value>, delta: &Map<String, Value>) -> Result<(), String> {
418	    for (k, dv) in delta {
419	        if acc.get(k).is_none_or(Value::is_null) {
420	            if has_indexed_entries(dv) {
421	                acc.insert(k.clone(), Value::Array(Vec::new()));
422	            } else {
423	                acc.insert(k.clone(), dv.clone());
424	                continue;
425	            }
426	        }
427	        if k == "index" || k == "type" {
428	            acc.insert(k.clone(), dv.clone());
429	            continue;
430	        }
431	        let av = acc.get_mut(k).expect("present");
432	        if let Some(sum) = py_add_numbers(av, dv) {
433	            *av = sum;
434	            continue;
435	        }
436	        match (av, dv) {
437	            (Value::String(a), Value::String(b)) => a.push_str(b),
438	            (Value::Object(a), Value::Object(b)) => accumulate_delta(a, b)?,
439	            (Value::Array(a), Value::Array(b)) => {
440	                if a.iter().all(py_scalar) && (!a.is_empty() || !has_indexed_entries(dv)) {
441	                    a.extend(b.iter().cloned());
442	                    continue;
443	                }
444	                for e in b {
445	                    let Value::Object(eo) = e else {
446	                        return Err("TypeError: list delta entry is not a dictionary".into());
447	                    };
448	                    let idx = eo.get("index").ok_or("RuntimeError: list delta entry without `index`")?;
449	                    let idx = py_int(idx).ok_or("TypeError: list delta entry `index` is not an integer")?;
450	                    match py_get(a.len(), idx) {
451	                        Some(p) => {
452	                            let Value::Object(target) = &mut a[p] else { return Err("TypeError: not handled yet".into()) };
453	                            accumulate_delta(target, eo)?;
454	                        }
455	                        None => a.insert(py_insert_at(a.len(), idx), e.clone()),
456	                    }
457	                }
458	            }
459	            _ => {} // different types: the accumulated value is kept
460	        }
461	    }
462	    Ok(())
463	}
464	
465	fn obj<'a>(v: Option<&'a Value>, what: &str) -> Result<&'a Map<String, Value>, String> {
466	    v.and_then(Value::as_object).ok_or_else(|| format!("AttributeError: {what}"))
467	}
468	
469	fn str_or_empty(v: Option<&Value>) -> String {
470	    v.and_then(Value::as_str).unwrap_or("").to_owned()
471	}
472	
473	/// The tool calls of one accumulated OpenAI message. A `function` body is run as a function call
474	/// whatever `type` says (openai-python appends an unknown type as is, openai-node runs every
475	/// non-`custom` type's `function`); a `custom` body is a custom call; anything else is `other`.
476	fn message_calls(choice: u32, m: &Map<String, Value>) -> Vec<ModelCall> {
477	    let mut out = Vec::new();
478	    if let Some(Value::Array(tc)) = m.get("tool_calls") {
479	        for e in tc {
480	            let Value::Object(e) = e else { continue };
481	            let (kind, name, arguments) = if let Some(Value::Object(f)) = e.get("function") {
482	                ("function", str_or_empty(f.get("name")), str_or_empty(f.get("arguments")))
483	            } else if let Some(Value::Object(c)) = e.get("custom") {
484	                ("custom", str_or_empty(c.get("name")), str_or_empty(c.get("input")))
485	            } else {
486	                // The core names a bodyless call by its `type`, or `unknown` when it has none.
487	                ("other", e.get("type").and_then(Value::as_str).unwrap_or("unknown").to_owned(), Value::Object(e.clone()).to_string())
488	            };
489	            out.push(ModelCall {
490	                choice,
491	                kind,
492	                name,
493	                arguments,
494	                parsed: false,
495	            });
496	        }
497	    }
498	    if let Some(Value::Object(fc)) = m.get("function_call") {
499	        out.push(ModelCall {
500	            choice,
501	            kind: "legacy",
502	            name: str_or_empty(fc.get("name")),
503	            arguments: str_or_empty(fc.get("arguments")),
504	            parsed: false,
505	        });
506	    }
507	    out
508	}
