537	        let mut out = Vec::new();
538	        for (i, c) in snap.iter().flatten().enumerate() {
539	            if let Some(Value::Object(m)) = c.get("message") {
540	                out.extend(message_calls(u32::try_from(i).expect("small"), m));
541	            }
542	        }
543	        out
544	    };
545	    let mut step = || -> Result<(), String> {
546	        for sse in py_events(bytes)? {
547	            if sse.data.starts_with("[DONE]") {
548	                break;
549	            }
550	            let v: Value = serde_json::from_str(&sse.data).map_err(|e| format!("JSONDecodeError: {e}"))?;
551	            if let Value::Object(m) = &v
552	                && py_truthy(m.get("error"))
553	            {
554	                return Err("APIError: error record".into());
555	            }
556	            if v.get("object").and_then(Value::as_str) != Some("chat.completion.chunk") {
557	                continue;
558	            }
559	            let Some(Value::Array(choices)) = v.get("choices") else {
560	                return Err("AttributeError: chunk.choices".into());
561	            };
562	            let choices: Vec<&Map<String, Value>> = choices.iter().map(|c| obj(Some(c), "choice")).collect::<Result<_, _>>()?;
563	            let Some(list) = snap.as_mut() else {
564	                let mut list: Vec<Value> = choices.iter().map(|c| Value::Object((*c).clone())).collect();
565	                for c in &choices {
566	                    let idx = py_int(c.get("index").ok_or("AttributeError: choice.index")?).ok_or("TypeError: choice.index")?;
567	                    let pos = py_get(list.len(), idx).ok_or("IndexError: list assignment index out of range")?;
568	                    list[pos] = py_new_choice(c)?;
569	                }
570	                snap = Some(list);
571	                continue;
572	            };
573	            for c in &choices {
574	                let idx = py_int(c.get("index").ok_or("AttributeError: choice.index")?).ok_or("TypeError: list indices must be integers")?;
575	                let pos = match py_get(list.len(), idx) {
576	                    Some(p) => {
577	                        let before = tool_types(&list[p]);
578	                        let Some(Value::Object(m)) = list[p].get_mut("message") else {
579	                            return Err("AttributeError: message".into());
580	                        };
581	                        accumulate_delta(m, obj(c.get("delta"), "choice.delta")?)?;
582	                        let after = tool_types(&list[p]);
583	                        for (i, t) in before.iter().enumerate() {
584	                            if t.as_deref() == Some("function") && after.get(i).and_then(Option::as_deref) != Some("function") {
585	                                return Err("AssertionError: new_tool.type == \"function\"".into());
586	                            }
587	                        }
588	                        p
589	                    }
590	                    None => {
591	                        list.push(py_new_choice(c)?);
592	                        list.len() - 1
593	                    }
594	                };
595	                if let Some(Value::Array(frags)) = c.get("delta").and_then(|d| d.get("tool_calls")) {
596	                    let len = match list[pos].pointer("/message/tool_calls") {
597	                        Some(Value::Array(a)) => a.len(),
598	                        _ => 0,
599	                    };
600	                    for f in frags {
601	                        let i = f.get("index").and_then(py_int).ok_or("TypeError: tool_call_chunk.index")?;
602	                        py_get(len, i).ok_or("IndexError: tool_calls[tool_call_chunk.index]")?;
603	                    }
604	                }
605	            }
606	        }
607	        Ok(())
608	    };
609	    let error = step().err();
610	    Run { calls: calls(&snap), error }
611	}
