659	    let mut step = || -> Result<(), String> {
660	        for sse in node_events(bytes) {
661	            if sse.data == "[DONE]" {
662	                break;
663	            }
664	            let v: Value = serde_json::from_str(&sse.data).map_err(|e| format!("SyntaxError: {e}"))?;
665	            if sse.event.as_deref() == Some("error") || js_truthy(v.get("error")) {
666	                return Err("APIError: error record".into());
667	            }
668	            let Some(Value::Array(cs)) = v.get("choices") else {
669	                return Err("TypeError: chunk.choices is not iterable".into());
670	            };
671	            for c in cs {
672	                let idx = js_index(c.get("index"), 128).ok_or("OpenAIError: invalid choice index")?;
673	                let ch = choices.entry(idx).or_default();
674	                if js_truthy(c.get("finish_reason")) {
675	                    ch.finish = c.get("finish_reason").cloned();
676	                }
677	                let Some(d) = c.get("delta").filter(|d| js_truthy(Some(d))) else { continue };
678	                if js_truthy(d.get("role")) {
679	                    ch.role = d.get("role").cloned();
680	                }
681	                if let Some(f) = d.get("function_call").filter(|f| js_truthy(Some(f))) {
682	                    match &mut ch.function_call {
683	                        Some(s) => {
684	                            if js_truthy(f.get("name")) {
685	                                s.insert("name".into(), f["name"].clone());
686	                            }
687	                            if js_truthy(f.get("arguments")) {
688	                                let prev = s.get("arguments").filter(|a| !a.is_null()).map(js_string).unwrap_or_default();
689	                                s.insert("arguments".into(), Value::String(prev + &js_string(&f["arguments"])));
690	                            }
691	                        }
692	                        None => ch.function_call = Some(f.as_object().cloned().unwrap_or_default()),
693	                    }
694	                }
695	                let Some(tcs) = d.get("tool_calls").filter(|t| js_truthy(Some(t))) else { continue };
696	                let Value::Array(tcs) = tcs else { return Err("TypeError: tool_calls is not iterable".into()) };
697	                for e in tcs {
698	                    let i = js_index(e.get("index"), 128).ok_or("OpenAIError: invalid tool call index")?;
699	                    let t = ch.tools.entry(i).or_default();
700	                    if js_truthy(e.get("id")) {
701	                        t.id = e.get("id").cloned();
702	                    }
703	                    if js_truthy(e.get("type")) {
704	                        t.ty = e.get("type").cloned();
705	                    }
706	                    if let Some(cu) = e.get("custom").filter(|x| js_truthy(Some(x))) {
707	                        let s = t.custom.get_or_insert_with(|| (cu.get("name").filter(|n| !n.is_null()).cloned().unwrap_or(json!("")), String::new()));
708	                        if js_truthy(cu.get("name")) {
709	                            s.0 = cu["name"].clone();
710	                        }
711	                        if js_truthy(cu.get("input")) {
712	                            s.1.push_str(&js_string(&cu["input"]));
713	                        }
714	                    }
715	                    if let Some(f) = e.get("function").filter(|x| js_truthy(Some(x))) {
716	                        let s = t.function.get_or_insert_with(|| (f.get("name").filter(|n| !n.is_null()).cloned().unwrap_or(json!("")), String::new()));
717	                        if js_truthy(f.get("name")) {
718	                            s.0 = f["name"].clone();
719	                        }
720	                        if let Some(a) = f.get("arguments").filter(|a| !a.is_null()) {
721	                            s.1.push_str(&js_string(a));
722	                        }
723	                    }
724	                }
725	            }
726	        }
727	        Ok(())
728	    };
729	    let mut error = step().err();
730	    let mut calls = Vec::new();
731	    for (idx, ch) in &choices {
732	        let choice = u32::try_from(*idx).expect("below 128");
733	        if error.is_none() && ch.finish.is_none() {
734	            error = Some(format!("OpenAIError: missing finish_reason for choice {idx}"));
735	        }
736	        if error.is_none() && ch.role.is_none() {
737	            error = Some(format!("OpenAIError: missing role for choice {idx}"));
738	        }
739	        for t in ch.tools.values() {
740	            let custom = t.ty.as_ref().and_then(Value::as_str) == Some("custom");
741	            if error.is_none() && t.ty.is_none() {
742	                error = Some("OpenAIError: missing tool_calls[].type".into());
743	            }
744	            let (kind, body) = if custom { ("custom", &t.custom) } else { ("function", &t.function) };
745	            match body {
746	                Some((name, arguments)) => calls.push(ModelCall {
747	                    choice,
748	                    kind,
749	                    name: js_string(name),
750	                    arguments: arguments.clone(),
751	                    parsed: false,
752	                }),
753	                None if error.is_none() => error = Some(format!("OpenAIError: missing tool_calls[].{kind}.name")),
754	                None => {}
755	            }
756	        }
757	        if let Some(fc) = &ch.function_call {
758	            if error.is_none() && (fc.get("arguments").is_none_or(Value::is_null) || !js_truthy(fc.get("name"))) {
759	                error = Some("OpenAIError: missing function_call.name or .arguments".into());
760	            }
761	            calls.push(ModelCall {
762	                choice,
763	                kind: "legacy",
764	                name: fc.get("name").map(js_string).unwrap_or_default(),
765	                arguments: fc.get("arguments").filter(|a| !a.is_null()).map(js_string).unwrap_or_default(),
766	                parsed: false,
767	            });
768	        }
769	    }
770	    Run { calls, error }
771	}
