930	                choice: 0,
931	                kind: "function",
932	                name: str_or_empty(e.get("name")),
933	                arguments: args.to_string(),
934	                parsed: true,
935	            })
936	        })
937	        .collect();
938	    if let Some(Value::Object(fc)) = kwargs.get("function_call") {
939	        calls.push(ModelCall {
940	            choice: 0,
941	            kind: "legacy",
942	            name: str_or_empty(fc.get("name")),
943	            arguments: str_or_empty(fc.get("arguments")),
944	            parsed: false,
945	        });
