950	/// LangChain `parse_partial_json`: a complete value as is; otherwise unterminated strings are
951	/// closed and open brackets closed in order, then trailing characters are dropped until the text
952	/// parses. A mismatched closing bracket gives `None`. Every candidate the SDK skips with its
953	/// decoder-offset shortcut fails the same way, so dropping one character at a time is equivalent.
954	/// SOURCE: langchain-core <not pinned: modelled only>, langchain_core/utils/json.py parse_partial_json.
955	pub fn lc_parse_partial_json(s: &str) -> Option<Value> {
956	    if let Ok(v) = serde_json::from_str(s) {
957	        return Some(v);
958	    }
959	    let (mut new, mut stack): (Vec<String>, Vec<char>) = (Vec::new(), Vec::new());
960	    let (mut inside, mut escaped) = (false, false);
961	    for ch in s.chars() {
962	        let mut out = ch.to_string();
963	        if inside {
964	            if ch == '"' && !escaped {
965	                inside = false;
966	            } else if ch == '\n' && !escaped {
967	                out = "\\n".to_owned();
968	            } else if ch == '\\' {
969	                escaped = !escaped;
970	            } else {
971	                escaped = false;
972	            }
973	        } else if ch == '"' {
974	            inside = true;
975	            escaped = false;
976	        } else if ch == '{' {
977	            stack.push('}');
978	        } else if ch == '[' {
979	            stack.push(']');
980	        } else if ch == '}' || ch == ']' {
981	            if stack.last() == Some(&ch) {
982	                stack.pop();
983	            } else {
984	                return None;
985	            }
986	        }
987	        new.push(out);
988	    }
989	    if inside {
990	        if escaped {
991	            new.pop();
992	        }
993	        new.push("\"".to_owned());
994	    }
995	    let closing: String = stack.iter().rev().collect();
996	    while !new.is_empty() {
997	        if let Ok(v) = serde_json::from_str(&format!("{}{closing}", new.concat())) {
998	            return Some(v);
999	        }
1000	        new.pop();
1001	    }
1002	    None
1003	}
1004	
1005	// ---- anthropic-python --------------------------------------------------------------------------
1006	
1007	/// jiter `from_json(buf, partial_mode=True)`: a truncated value is closed at the end of the input,
1008	/// an unfinished string, literal or number is dropped (with its key), anything invalid raises.
1009	///
1010	/// SOURCE: jiter 0.19.0 in partial mode, measured on 2026-11-14 (anthropic 2.3.0 requires
1011	/// `jiter<1,>=0.4.0`): `{"n":10.` -> `{}`, `{"n":1e` -> `{}`, `{"n":-` -> `{}`,
1012	/// `{"a":"x","n":10.` -> `{"a":"x"}`, `{"n":10` -> `{"n":10}`.
1013	struct Partial<'a> {
1014	    b: &'a [u8],
1015	    i: usize,
1016	}
1017	
1018	impl Partial<'_> {
1019	    fn ws(&mut self) {
1020	        while self.i < self.b.len() && matches!(self.b[self.i], b' ' | b'\t' | b'\n' | b'\r') {
1021	            self.i += 1;
1022	        }
1023	    }
1024	    fn eof(&self) -> bool {
1025	        self.i >= self.b.len()
1026	    }
1027	    /// `Ok(None)`: the input ended inside this value.
1028	    fn value(&mut self) -> Result<Option<Value>, String> {
1029	        self.ws();
1030	        if self.eof() {
1031	            return Ok(None);
1032	        }
1033	        match self.b[self.i] {
1034	            b'{' => {
1035	                self.i += 1;
1036	                let mut m = Map::new();
1037	                loop {
1038	                    self.ws();
1039	                    if self.eof() {
1040	                        return Ok(Some(Value::Object(m)));
1041	                    }
1042	                    if self.b[self.i] == b'}' {
1043	                        self.i += 1;
1044	                        return Ok(Some(Value::Object(m)));
1045	                    }
1046	                    // jiter 0.19.0 rejects a non-string key, even in partial mode.
1047	                    if self.b[self.i] != b'"' {
1048	                        return Err("ValueError: key must be a string".into());
1049	                    }
1050	                    let Some(Value::String(k)) = self.value()? else { return Ok(Some(Value::Object(m))) };
1051	                    self.ws();
1052	                    if self.eof() {
1053	                        return Ok(Some(Value::Object(m)));
1054	                    }
1055	                    if self.b[self.i] != b':' {
1056	                        return Err("ValueError: expected ':'".into());
1057	                    }
1058	                    self.i += 1;
1059	                    let Some(v) = self.value()? else { return Ok(Some(Value::Object(m))) };
1060	                    m.insert(k, v);
1061	                    self.ws();
1062	                    if self.eof() {
1063	                        return Ok(Some(Value::Object(m)));
1064	                    }
1065	                    match self.b[self.i] {
1066	                        b',' => self.i += 1,
1067	                        b'}' => {
1068	                            self.i += 1;
1069	                            return Ok(Some(Value::Object(m)));
1070	                        }
1071	                        _ => return Err("ValueError: expected ',' or '}'".into()),
1072	                    }
1073	                }
1074	            }
1075	            b'[' => {
1076	                self.i += 1;
1077	                let mut a = Vec::new();
1078	                loop {
1079	                    self.ws();
1080	                    if self.eof() {
1081	                        return Ok(Some(Value::Array(a)));
1082	                    }
1083	                    if self.b[self.i] == b']' {
1084	                        self.i += 1;
1085	                        return Ok(Some(Value::Array(a)));
1086	                    }
1087	                    let Some(v) = self.value()? else { return Ok(Some(Value::Array(a))) };
1088	                    a.push(v);
1089	                    self.ws();
1090	                    if self.eof() {
1091	                        return Ok(Some(Value::Array(a)));
1092	                    }
1093	                    match self.b[self.i] {
1094	                        b',' => self.i += 1,
1095	                        b']' => {
1096	                            self.i += 1;
1097	                            return Ok(Some(Value::Array(a)));
1098	                        }
1099	                        _ => return Err("ValueError: expected ',' or ']'".into()),
1100	                    }
1101	                }
1102	            }
1103	            b'"' => {
1104	                let start = self.i;
1105	                self.i += 1;
1106	                while self.i < self.b.len() {
1107	                    match self.b[self.i] {
1108	                        b'\\' => self.i += 2,
1109	                        b'"' => {
1110	                            self.i += 1;
1111	                            return serde_json::from_slice(&self.b[start..self.i]).map(Some).map_err(|e| format!("ValueError: {e}"));
1112	                        }
1113	                        _ => self.i += 1,
1114	                    }
1115	                }
1116	                Ok(None)
1117	            }
1118	            _ => {
1119	                let start = self.i;
1120	                while self.i < self.b.len() && !matches!(self.b[self.i], b',' | b'}' | b']' | b' ' | b'\t' | b'\n' | b'\r') {
1121	                    self.i += 1;
1122	                }
1123	                let tok = &self.b[start..self.i];
1124	                match serde_json::from_slice::<Value>(tok) {
1125	                    Ok(v) if !v.is_object() && !v.is_array() && !v.is_string() => Ok(Some(v)),
1126	                    _ if self.eof() && [&b"true"[..], b"false", b"null"].iter().any(|l| l.starts_with(tok)) => Ok(None),
1127	                    // An unfinished number at the end of the input (`10.`, `1e`, `-`) is dropped with its key.
1128	                    _ if self.eof() && number_prefix(tok) => Ok(None),
1129	                    _ => Err(format!("ValueError: invalid token {:?}", String::from_utf8_lossy(tok))),
1130	                }
1131	            }
1132	        }
1133	    }
1134	}
1135	
1136	/// Whether `tok` is a non-empty prefix of a JSON number
1137	/// (`-? (0 | [1-9][0-9]*) (\.[0-9]+)? ([eE][+-]?[0-9]+)?`). jiter 0.19.0 raises on any other token:
1138	/// `01`, `1e--`, `+1` and `--` raise, `-`, `1e`, `1e-` and `10.` are dropped (measured 2026-11-14).
1139	fn number_prefix(tok: &[u8]) -> bool {
1140	    #[derive(Clone, Copy)]
1141	    enum S {
1142	        Start,
1143	        Minus,
1144	        Zero,
1145	        Int,
1146	        Dot,
1147	        Frac,
1148	        E,
1149	        ESign,
1150	        Exp,
1151	    }
1152	    let mut s = S::Start;
1153	    for &c in tok {
1154	        s = match (s, c) {
1155	            (S::Start, b'-') => S::Minus,
1156	            (S::Start | S::Minus, b'0') => S::Zero,
1157	            (S::Start | S::Minus, b'1'..=b'9') | (S::Int, b'0'..=b'9') => S::Int,
1158	            (S::Zero | S::Int, b'.') => S::Dot,
1159	            (S::Dot | S::Frac, b'0'..=b'9') => S::Frac,
1160	            (S::Zero | S::Int | S::Frac, b'e' | b'E') => S::E,
1161	            (S::E, b'+' | b'-') => S::ESign,
1162	            (S::E | S::ESign | S::Exp, b'0'..=b'9') => S::Exp,
1163	            _ => return false,
1164	        };
1165	    }
1166	    !tok.is_empty()
1167	}
1168	
1169	pub fn partial_json(buf: &str) -> Result<Value, String> {
1170	    let mut p = Partial { b: buf.as_bytes(), i: 0 };
1171	    let v = p.value()?.ok_or("ValueError: EOF while parsing a value")?;
1172	    p.ws();
1173	    if !p.eof() {
1174	        return Err("ValueError: trailing characters".into());
1175	    }
1176	    Ok(v)
1177	}
1178	
1179	const NOT_RUN_BY_CLIENT: [&str; 5] = ["text", "thinking", "redacted_thinking", "server_tool_use", "mcp_tool_use"];
1180	
1181	/// anthropic-python `MessageStream`. The raw stream SKIPS records whose `event:` is absent or
1182	/// `ping`, raises on `error`, skips empty data, and decodes the rest by `data.type` (the event
1183	/// name is not compared with it). The first event must be `message_start`, whose
1184	/// `message.content` seeds the snapshot. `content_block_start` APPENDS a block whatever its index;
1185	/// deltas and stops look up `content[event.index]` by Python list indexing. An `input_json_delta`
1186	/// for a `tool_use` or `server_tool_use` block is appended to a buffer keyed by `event.index` and
1187	/// partial-parsed into `input`. A `message_delta` writes `snapshot.usage.output_tokens`, so a
1188	/// `message_start` without a `usage` object makes it raise (checked against 2.3.0 by the
1189	/// SMA-749 SDK conformance tests). Nothing stops at `message_stop`.
1190	/// SOURCE: anthropic-python 2.3.0, src/anthropic/lib/streaming/_messages.py
1191	/// accumulate_event; src/anthropic/_streaming.py Stream.__stream__.
1192	pub fn run_anthropic_python(bytes: &[u8]) -> Run {
1193	    let mut snap: Option<Vec<Map<String, Value>>> = None;
1194	    // Whether `message_start.message.usage` was an object: the snapshot is built with `construct`, so a missing one is `None`.
1195	    let mut snap_has_usage = false;
1196	    let mut bufs: BTreeMap<i64, String> = BTreeMap::new();
1197	    let mut step = || -> Result<(), String> {
1198	        for sse in py_events(bytes)? {
1199	            match sse.event.as_deref() {
1200	                None | Some("ping") => continue,
1201	                Some("error") => return Err("APIStatusError: error event".into()),
1202	                _ => {}
1203	            }
1204	            if sse.data.is_empty() {
1205	                continue;
1206	            }
1207	            let v: Value = serde_json::from_str(&sse.data).map_err(|e| format!("JSONDecodeError: {e}"))?;
1208	            let ty = v.get("type").and_then(Value::as_str).unwrap_or("");
1209	            let Some(content) = snap.as_mut() else {
1210	                if ty != "message_start" {
1211	                    return Err(format!("RuntimeError: Unexpected event order, got {ty} before \"message_start\""));
1212	                }
1213	                let blocks = match v.pointer("/message/content") {
1214	                    None | Some(Value::Null) => Vec::new(),
1215	                    Some(Value::Array(a)) => a.iter().map(|b| obj(Some(b), "content block").cloned()).collect::<Result<_, _>>()?,
1216	                    Some(_) => return Err("TypeError: message.content".into()),
1217	                };
1218	                let message = obj(v.get("message"), "event.message")?;
1219	                snap_has_usage = matches!(message.get("usage"), Some(Value::Object(_)));
1220	                snap = Some(blocks);
1221	                continue;
1222	            };
1223	            match ty {
1224	                "content_block_start" => content.push(obj(v.get("content_block"), "event.content_block")?.clone()),
1225	                "content_block_delta" => {
1226	                    let idx = v.get("index").and_then(py_int).ok_or("TypeError: event.index")?;
1227	                    let pos = py_get(content.len(), idx).ok_or("IndexError: list index out of range")?;
1228	                    let delta = obj(v.get("delta"), "event.delta")?;
1229	                    let block_ty = content[pos].get("type").and_then(Value::as_str).unwrap_or("");
1230	                    if delta.get("type").and_then(Value::as_str) == Some("input_json_delta") && (block_ty == "tool_use" || block_ty == "server_tool_use") {
1231	                        let pj = delta.get("partial_json").and_then(Value::as_str).ok_or("TypeError: partial_json is not a string")?;
1232	                        let buf = bufs.entry(idx).or_default();
1233	                        buf.push_str(pj);
1234	                        if !buf.is_empty() {
1235	                            let input = partial_json(buf)?;
1236	                            content[pos].insert("input".into(), input);
1237	                        }
1238	                    }
1239	                }
1240	                "content_block_stop" => {
1241	                    let idx = v.get("index").and_then(py_int).ok_or("TypeError: event.index")?;
1242	                    py_get(content.len(), idx).ok_or("IndexError: list index out of range")?;
1243	                }
1244	                "message_delta" => {
1245	                    obj(v.get("delta"), "event.delta")?;
1246	                    obj(v.get("usage"), "event.usage")?;
1247	                    // `current_snapshot.usage.output_tokens = event.usage.output_tokens`
1248	                    if !snap_has_usage {
1249	                        return Err("AttributeError: 'NoneType' object has no attribute 'output_tokens'".into());
1250	                    }
1251	                }
1252	                _ => {}
1253	            }
1254	        }
1255	        Ok(())
1256	    };
1257	    let error = step().err();
1258	    let calls = snap
1259	        .unwrap_or_default()
1260	        .iter()
1261	        .filter_map(|b| {
1262	            let t = b.get("type").and_then(Value::as_str).unwrap_or("");
1263	            if NOT_RUN_BY_CLIENT.contains(&t) || t.ends_with("_tool_result") {
1264	                return None;
1265	            }
1266	            let (kind, arguments) = if t == "tool_use" {
1267	                ("tool_use", b.get("input").cloned().unwrap_or(Value::Null).to_string())
1268	            } else {
1269	                ("other", Value::Object(b.clone()).to_string())
1270	            };
1271	            Some(ModelCall {
1272	                choice: 0,
1273	                kind,
1274	                name: b.get("name").and_then(Value::as_str).unwrap_or(t).to_owned(),
1275	                arguments,
1276	                parsed: kind == "tool_use",
1277	            })
1278	        })
1279	        .collect();
1280	    Run { calls, error }
1281	}
