172	/// One dispatched SSE event.
173	#[derive(Debug, Clone, PartialEq, Eq)]
174	pub struct Sse {
175	    pub event: Option<String>,
176	    pub data: String,
177	}
178	
179	/// Lines split at CRLF, CR or LF; the last element is the unterminated rest (maybe empty).
180	fn lines(bytes: &[u8]) -> (Vec<&[u8]>, &[u8]) {
181	    let mut out = Vec::new();
182	    let mut start = 0;
183	    let mut i = 0;
184	    while i < bytes.len() {
185	        match bytes[i] {
186	            b'\n' => {
187	                out.push(&bytes[start..i]);
188	                start = i + 1;
189	            }
190	            b'\r' => {
191	                out.push(&bytes[start..i]);
192	                if bytes.get(i + 1) == Some(&b'\n') {
193	                    i += 1;
194	                }
195	                start = i + 1;
196	            }
197	            _ => {}
198	        }
199	        i += 1;
200	    }
201	    (out, &bytes[start..])
202	}
203	
204	/// The `SSEDecoder` of openai-python and anthropic-python: lines split at CR, LF and CRLF, each
205	/// line decoded as strict UTF-8 (a bad byte raises), no BOM handling, a dispatch on a blank line
206	/// whenever an event name, data, an id or a retry was seen (so `event:` without `data:` dispatches
207	/// an empty data string), and no dispatch at the end of the stream without a blank line.
208	/// SOURCE: openai-python 3.40.0, src/openai/_streaming.py SSEDecoder.decode and
209	/// _SSELineDecoder; anthropic-python 2.3.0, src/anthropic/_streaming.py SSEDecoder.
210	pub fn py_events(bytes: &[u8]) -> Result<Vec<Sse>, String> {
211	    let (ls, rest) = lines(bytes);
212	    let mut out = Vec::new();
213	    let (mut event, mut data, mut last_id, mut retry): (Option<String>, Vec<String>, Option<String>, Option<i64>) = (None, Vec::new(), None, None);
214	    for raw in ls {
215	        let line = std::str::from_utf8(raw).map_err(|e| format!("UnicodeDecodeError: {e}"))?;
216	        if line.is_empty() {
217	            if event.as_deref().is_none_or(str::is_empty) && data.is_empty() && last_id.as_deref().is_none_or(str::is_empty) && retry.is_none() {
218	                continue;
219	            }
220	            out.push(Sse {
221	                event: event.take(),
222	                data: data.join("\n"),
223	            });
224	            data.clear();
225	            retry = None;
226	            continue;
227	        }
228	        if line.starts_with(':') {
229	            continue;
230	        }
231	        let (name, value) = match line.find(':') {
232	            Some(i) => (&line[..i], line[i + 1..].strip_prefix(' ').unwrap_or(&line[i + 1..])),
233	            None => (line, ""),
234	        };
235	        match name {
236	            "event" => event = Some(value.to_owned()),
237	            "data" => data.push(value.to_owned()),
238	            "id" if !value.contains('\0') => last_id = Some(value.to_owned()),
239	            "retry" => retry = value.parse().ok().or(retry),
240	            _ => {}
241	        }
242	    }
243	    std::str::from_utf8(rest).map_err(|e| format!("UnicodeDecodeError: {e}"))?;
244	    Ok(out)
245	}
246	
247	/// openai-node's `SSEDecoder` behind `LineDecoder` and a `TextDecoder`: lossy UTF-8 with the BOM
248	/// stripped, lines split at CR, LF and CRLF, `event` and `data` fields only, a dispatch on a blank
249	/// line when an event name or a data line was seen, and a flush of the pending event at the end.
250	/// SOURCE: openai-node <not pinned: modelled only>, src/core/streaming.ts SSEDecoder.
251	pub fn node_events(bytes: &[u8]) -> Vec<Sse> {
252	    let text = String::from_utf8_lossy(bytes);
253	    let text = text.strip_prefix('\u{feff}').unwrap_or(&text);
254	    let (ls, rest) = lines(text.as_bytes());
255	    let mut all: Vec<&[u8]> = ls;
256	    if !rest.is_empty() {
257	        all.push(rest);
258	    }
259	    let mut out = Vec::new();
260	    let (mut event, mut data): (Option<String>, Vec<String>) = (None, Vec::new());
261	    let dispatch = |event: &mut Option<String>, data: &mut Vec<String>, out: &mut Vec<Sse>| {
262	        if event.as_deref().is_none_or(str::is_empty) && data.is_empty() {
263	            return;
264	        }
265	        out.push(Sse {
266	            event: event.take(),
267	            data: data.join("\n"),
268	        });
269	        data.clear();
270	    };
271	    for raw in all {
272	        let line = std::str::from_utf8(raw).expect("lossy text is UTF-8");
273	        if line.is_empty() {
274	            dispatch(&mut event, &mut data, &mut out);
275	            continue;
276	        }
277	        if line.starts_with(':') {
278	            continue;
279	        }
280	        let (name, value) = match line.find(':') {
281	            Some(i) => (&line[..i], line[i + 1..].strip_prefix(' ').unwrap_or(&line[i + 1..])),
282	            None => (line, ""),
283	        };
284	        match name {
285	            "event" => event = Some(value.to_owned()),
286	            "data" => data.push(value.to_owned()),
287	            _ => {}
288	        }
289	    }
290	    dispatch(&mut event, &mut data, &mut out);
291	    out
292	}
