413	/// openai-python `accumulate_delta`. `index` and `type` are replaced, strings and numbers added,
414	/// dicts merged, indexed lists merged by `list[index]` (Python indexing, `insert` on IndexError).
415	/// A value of a different type is kept, not replaced.
416	/// SOURCE: openai-python 3.40.0, src/openai/lib/streaming/_deltas.py accumulate_delta.
417	fn accumulate_delta(acc: &mut Map<String, Value>, delta: &Map<String, Value>) -> Result<(), String> {
418	    for (k, dv) in delta {
419	        if acc.get(k).is_none_or(Value::is_null) {
420	            if has_indexed_entries(dv) {
421	                acc.insert(k.clone(), Value::Array(Vec::new()));
422	            } else {
423	                acc.insert(k.clone(), dv.clone());
424	                continue;
425	            }
426	        }
427	        if k == "index" || k == "type" {
428	            acc.insert(k.clone(), dv.clone());
429	            continue;
430	        }
431	        let av = acc.get_mut(k).expect("present");
432	        if let Some(sum) = py_add_numbers(av, dv) {
433	            *av = sum;
434	            continue;
435	        }
436	        match (av, dv) {
437	            (Value::String(a), Value::String(b)) => a.push_str(b),
438	            (Value::Object(a), Value::Object(b)) => accumulate_delta(a, b)?,
439	            (Value::Array(a), Value::Array(b)) => {
440	                if a.iter().all(py_scalar) && (!a.is_empty() || !has_indexed_entries(dv)) {
441	                    a.extend(b.iter().cloned());
442	                    continue;
443	                }
444	                for e in b {
445	                    let Value::Object(eo) = e else {
446	                        return Err("TypeError: list delta entry is not a dictionary".into());
447	                    };
448	                    let idx = eo.get("index").ok_or("RuntimeError: list delta entry without `index`")?;
449	                    let idx = py_int(idx).ok_or("TypeError: list delta entry `index` is not an integer")?;
450	                    match py_get(a.len(), idx) {
451	                        Some(p) => {
452	                            let Value::Object(target) = &mut a[p] else { return Err("TypeError: not handled yet".into()) };
453	                            accumulate_delta(target, eo)?;
454	                        }
455	                        None => a.insert(py_insert_at(a.len(), idx), e.clone()),
456	                    }
457	                }
458	            }
459	            _ => {} // different types: the accumulated value is kept
460	        }
461	    }
462	    Ok(())
463	}
