473	/// The tool calls of one accumulated OpenAI message. A `function` body is run as a function call
474	/// whatever `type` says (openai-python appends an unknown type as is, openai-node runs every
475	/// non-`custom` type's `function`); a `custom` body is a custom call; anything else is `other`.
476	fn message_calls(choice: u32, m: &Map<String, Value>) -> Vec<ModelCall> {
477	    let mut out = Vec::new();
478	    if let Some(Value::Array(tc)) = m.get("tool_calls") {
479	        for e in tc {
480	            let Value::Object(e) = e else { continue };
481	            let (kind, name, arguments) = if let Some(Value::Object(f)) = e.get("function") {
482	                ("function", str_or_empty(f.get("name")), str_or_empty(f.get("arguments")))
483	            } else if let Some(Value::Object(c)) = e.get("custom") {
484	                ("custom", str_or_empty(c.get("name")), str_or_empty(c.get("input")))
485	            } else {
486	                // The core names a bodyless call by its `type`, or `unknown` when it has none.
487	                ("other", e.get("type").and_then(Value::as_str).unwrap_or("unknown").to_owned(), Value::Object(e.clone()).to_string())
488	            };
489	            out.push(ModelCall {
490	                choice,
491	                kind,
492	                name,
493	                arguments,
494	                parsed: false,
495	            });
496	        }
497	    }
498	    if let Some(Value::Object(fc)) = m.get("function_call") {
499	        out.push(ModelCall {
500	            choice,
501	            kind: "legacy",
502	            name: str_or_empty(fc.get("name")),
503	            arguments: str_or_empty(fc.get("arguments")),
504	            parsed: false,
505	        });
506	    }
507	    out
508	}
