510	/// A choice snapshot as `_convert_initial_chunk_into_snapshot` and the IndexError branch build it.
511	fn py_new_choice(c: &Map<String, Value>) -> Result<Value, String> {
512	    let mut snap = c.clone();
513	    snap.remove("delta");
514	    let mut message = Map::new();
515	    accumulate_delta(&mut message, obj(c.get("delta"), "choice.delta")?)?;
516	    snap.insert("message".into(), Value::Object(message));
517	    Ok(Value::Object(snap))
518	}
