715	                    if let Some(f) = e.get("function").filter(|x| js_truthy(Some(x))) {
716	                        let s = t.function.get_or_insert_with(|| (f.get("name").filter(|n| !n.is_null()).cloned().unwrap_or(json!("")), String::new()));
717	                        if js_truthy(f.get("name")) {
718	                            s.0 = f["name"].clone();
719	                        }
720	                        if let Some(a) = f.get("arguments").filter(|a| !a.is_null()) {
