743	            }
744	            let (kind, body) = if custom { ("custom", &t.custom) } else { ("function", &t.function) };
745	            match body {
746	                Some((name, arguments)) => calls.push(ModelCall {
747	                    choice,
748	                    kind,
749	                    name: js_string(name),
750	                    arguments: arguments.clone(),
751	                    parsed: false,
752	                }),
753	                None if error.is_none() => error = Some(format!("OpenAIError: missing tool_calls[].{kind}.name")),
754	                None => {}
755	            }
756	        }
757	        if let Some(fc) = &ch.function_call {
758	            if error.is_none() && (fc.get("arguments").is_none_or(Value::is_null) || !js_truthy(fc.get("name"))) {
