780	/// LangChain `merge_dicts` on two flat dicts: `None` on the left is replaced, `None` on the right
781	/// ignored, strings concatenated except an equal `id`, equal values kept, a type change raises.
782	/// SOURCE: langchain-core <not pinned: modelled only>, langchain_core/utils/_merge.py merge_dicts.
783	fn lc_merge_dicts(left: &mut Map<String, Value>, right: &Map<String, Value>) -> Result<(), String> {
784	    for (k, rv) in right {
785	        let Some(lv) = left.get_mut(k) else {
786	            left.insert(k.clone(), rv.clone());
787	            continue;
788	        };
789	        if lv.is_null() && !rv.is_null() {
790	            *lv = rv.clone();
791	            continue;
792	        }
793	        if rv.is_null() || *lv == *rv && !lv.is_string() {
794	            continue;
795	        }
796	        let same_type = std::mem::discriminant(lv) == std::mem::discriminant(rv) && (lv.is_i64() || lv.is_u64()) == (rv.is_i64() || rv.is_u64());
797	        if !same_type {
798	            return Err(format!("TypeError: additional_kwargs[{k:?}] already exists with a different type"));
799	        }
800	        match (lv, rv) {
801	            (Value::String(l), Value::String(r)) => {
802	                if !(k == "id" && l == r) {
803	                    l.push_str(r);
804	                }
805	            }
806	            (Value::Object(l), Value::Object(r)) => lc_merge_dicts(l, r)?,
807	            (Value::Number(l), Value::Number(r)) if k != "index" => {
808	                *l = py_add_numbers(&Value::Number(l.clone()), &Value::Number(r.clone()))
809	                    .and_then(|v| v.as_number().cloned())
810	                    .ok_or("TypeError")?;
811	            }
812	            (Value::Number(l), Value::Number(r)) => *l = r.clone(), // `index` is replaced
813	            (Value::Array(l), Value::Array(r)) => l.extend(r.iter().cloned()),
814	            _ => return Err(format!("TypeError: unsupported type for {k:?}")),
815	        }
816	    }
817	    Ok(())
818	}
