/// The fixed name of a built-in client-run kind (§ 5).
fn fixed_name(kind: ToolCallKind) -> Option<&'static str> {
    match kind {
        ToolCallKind::Computer => Some("computer"),
        ToolCallKind::LocalShell => Some("local_shell"),
        ToolCallKind::Shell => Some("shell"),
