        ToolCallKind::ToolSearch => Some("tool_search"),
        _ => None,
    }
}

fn text_of(item: &Map<String, Value>, key: &'static str) -> Result<String, Malformed> {
    match item.get(key) {
        Some(Value::String(s)) => Ok(s.clone()),
        _ => Err(Malformed(key)),
    }
}

/// `(namespace, name)` of a client-run item (§ 5).
